head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useCtrlOnMultisort]<br/>sortable=true, preventMultisort=false 일때 Ctrl 키를 사용하여 다중 정렬을 실행할지 설정합니다.",
    "validation" : [
        "true(기본값) 설정 시 Ctrl 키를 누른 상태에서 Header Column 을 클릭/더블클릭하면 다중 정렬, Ctrl 안 누르면 단일 정렬됩니다.",
        "false 설정 시 Ctrl 안 누른 상태에서 Header Column 을 클릭/더블클릭하면 다중 정렬, Ctrl 누른 상태로 클릭하면 단일 정렬됩니다.",
        "preventMultisort=true 이면 useCtrlOnMultisort 속성은 무시됩니다.",
        "Header Column 의 개별 sortable 설정 시 GridView 의 sortable 이 무시되고, 미설정 시 GridView 의 sortable 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 포함)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건값 조회 (gdl_boolean 바인딩 con_ 셀렉트는 getText() 가 ''/true/false 라벨을 반환, getValue 는 1/2/3)
    let conUseCtrl = con_useCtrlOnMultisort.getText();
    let conPrevent = con_preventMultisort.getText();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    //  - 화살표는 유니코드 → 사용 (ASCII -> 금지)
    let lblUseCtrl = (conUseCtrl === '') ? '미설정(기본 true)' : conUseCtrl;
    let lblPrevent = (conPrevent === '') ? '미설정(기본 false)' : conPrevent;
    $c.gcm.createLabel('label="sortable=true, sortEvent=onclick, useCtrlOnMultisort=' + lblUseCtrl + ', preventMultisort=' + lblPrevent + ' 로 GridView 생성. col1·col3·col4 는 정렬 가능(col1 개별true / col3·col4 GridView 적용), col2(개별false)는 정렬 불가. 헤더 클릭으로 정렬되고 onsort 에서 정렬 배열(length>1 이면 다중, 1 이면 단일)이 출력됩니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (col1=text, col2=number, col3=text, col4=number)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 정렬 시 순서가 바뀌도록 값을 섞어서 4행 구성
    let jsonData = [
        { "col1": "C", "col2": 200, "col3": "Cc", "col4": 30 },
        { "col1": "A", "col2": 400, "col3": "Aa", "col4": 10 },
        { "col1": "D", "col2": 100, "col3": "Dd", "col4": 40 },
        { "col1": "B", "col2": 300, "col3": "Bb", "col4": 20 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수, 빈 문자열 value 는 자동 제외 → 속성 미부여)
    //  - sortable="true"        : 개별 미설정 Header(col3, col4) 의 기본 정렬 가능 (@spec)
    //  - sortEvent="onclick"    : 헤더 클릭으로 정렬 트리거
    //  - rowNumVisible/rowStatusVisible : RowNum/RowStatus Column 표시
    //  - useCtrlOnMultisort / preventMultisort : con 셀렉트 getText() 값 (미설정 시 '' → 키 자체 미부여)
    let properties = {
        dataList: "data:dlt_bind",
        sortable: "true",
        sortEvent: "onclick",
        rowNumVisible: "true",
        rowStatusVisible: "true",
        useCtrlOnMultisort: conUseCtrl,
        preventMultisort: conPrevent,
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Body 4컬럼, 단일 Row 헤더 - 병합 금지)
    //  개별 sortable : hcol1=true(GridView 무시) / hcol2=false(GridView 무시, 정렬불가) / hcol3·hcol4=미설정(GridView true 적용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:660px;height:200px;" ev:onsort="scwin.target1_onsort">';
    strTarget += '<w2:caption style="" id="caption1" value="useCtrlOnMultisort 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    // col1 : 개별 sortable=true
    strTarget += '<w2:column width="120" style="" inputType="text" sortable="true" id="hcol1" value="col1(개별true)"></w2:column>';
    // col2 : 개별 sortable=false (GridView true 무시 → 정렬 불가)
    strTarget += '<w2:column width="120" style="" inputType="text" sortable="false" id="hcol2" value="col2(개별false)"></w2:column>';
    // col3 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="col3(GridView)"></w2:column>';
    // col4 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol4" value="col4(GridView)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onsort 이벤트 핸들러
//  - 사용자가 sortable 헤더를 클릭(또는 Ctrl+클릭)해 정렬하면 발생
//  - getSortableStatus() 로 현재 정렬 배열 조회 : length>1 이면 다중 정렬, 1 이면 단일 정렬
scwin.target1_onsort = function (info) {
    let status = target1.getSortableStatus();
    let mode = (status.length > 1) ? "다중 정렬" : (status.length === 1 ? "단일 정렬" : "정렬 해제");
    wf_body_bottom.getObj("scwin").setReturnValue("[onsort] " + mode + " (배열 length=" + status.length + ") : " + JSON.stringify(status));
};
